import { expect, test } from 'bun:test';
import { parseRollout } from '../src/rollout-reader';

function rollout(...payloads: Record<string, unknown>[]) {
  return payloads.map(payload => JSON.stringify({ type: 'response_item', payload })).join('\n');
}

test('retains all messages without usable item IDs, including repeated text', () => {
  const events = parseRollout(rollout(
    { type: 'message', role: 'user', content: 'first' },
    { type: 'message', role: 'assistant', content: 'second' },
    { type: 'message', role: 'user', content: 'first' },
    { type: 'message', role: 'user', id: null, content: 'null ID' },
    { type: 'message', role: 'assistant', id: '', content: 'empty ID' },
  )).events;

  expect(events).toEqual([
    { kind: 'user_message', id: '', text: 'first' },
    { kind: 'assistant_message', id: '', text: 'second' },
    { kind: 'user_message', id: '', text: 'first' },
    { kind: 'user_message', id: '', text: 'null ID' },
    { kind: 'assistant_message', id: '', text: 'empty ID' },
  ]);
});

test.each(['function', 'custom_tool'])('%s calls and outputs deduplicate separately by call_id when item IDs are missing', prefix => {
  const call = { type: `${prefix}_call`, call_id: 'shared', name: 'run', arguments: '{"path":"test"}' };
  const output = { type: `${prefix}_call_output`, call_id: 'shared', output: 'done' };
  const events = parseRollout(rollout(
    call, output, call, output,
    { ...call, call_id: 'other' },
    { ...output, call_id: 'other' },
  )).events;

  expect(events).toEqual([
    { kind: 'tool_call', id: '', callId: 'shared', name: 'run', args: { path: 'test' } },
    { kind: 'tool_output', id: '', callId: 'shared', text: 'done' },
    { kind: 'tool_call', id: '', callId: 'other', name: 'run', args: { path: 'test' } },
    { kind: 'tool_output', id: '', callId: 'other', text: 'done' },
  ]);
});

test('explicit item IDs take precedence over call_id and still deduplicate globally', () => {
  const events = parseRollout(rollout(
    { type: 'function_call', id: 'one', call_id: 'shared', name: 'first' },
    { type: 'function_call', id: 'two', call_id: 'shared', name: 'second' },
    { type: 'function_call', id: 'one', call_id: 'changed', name: 'replay' },
    { type: 'message', id: 'two', role: 'user', content: 'replay' },
    { type: 'message', id: 'message', role: 'user', content: 'original' },
    { type: 'message', id: 'message', role: 'user', content: 'replay' },
  )).events;

  expect(events.map(event => event.id)).toEqual(['one', 'two', 'message']);
});

test('explicit IDs do not collide with fallback tool identities or ID-less messages', () => {
  const events = parseRollout(rollout(
    { type: 'message', id: 'tool_call:shared', role: 'user', content: 'explicit' },
    { type: 'function_call', call_id: 'shared', name: 'run' },
    { type: 'function_call_output', call_id: 'shared', output: 'done' },
    { type: 'message', role: 'assistant', content: 'after tool' },
  )).events;

  expect(events.map(event => event.kind)).toEqual(['user_message', 'tool_call', 'tool_output', 'assistant_message']);
});

test('tool events without either item IDs or call IDs are retained', () => {
  const call = { type: 'function_call', name: 'run' };
  const output = { type: 'function_call_output', output: 'done' };
  expect(parseRollout(rollout(call, output, call, output)).events).toHaveLength(4);
});

test('partial trailing JSON preserves earlier ID-less events', () => {
  const jsonl = rollout(
    { type: 'message', role: 'user', content: 'first' },
    { type: 'message', role: 'assistant', content: 'second' },
  );
  const complete = parseRollout(jsonl);
  expect(complete.events).toHaveLength(2);
  expect(parseRollout(jsonl + '\n{"type":"response_item","payload":')).toEqual(complete);
});
